#include <bits/stdc++.h>
using namespace std;

static char buf[1 << 16];
static size_t blen = 0, bpos = 0;
static inline int gc() {
    if (bpos == blen) {
        blen = fread(buf, 1, sizeof buf, stdin);
        bpos = 0;
        if (!blen) return -1;
    }
    return buf[bpos++];
}
static string token() {
    int c = gc();
    while (c != -1 && c <= ' ') c = gc();
    string s;
    while (c > ' ') { s += (char)c; c = gc(); }
    return s;
}

int main() {
    int T = stoi(token());
    unordered_map<string, int> id;
    vector<string> names;
    vector<vector<int>> trans(T);
    for (int t = 0; t < T; t++) {
        int k = stoi(token());
        for (int i = 0; i < k; i++) {
            string s = token();
            auto it = id.find(s);
            int x;
            if (it == id.end()) { x = (int)names.size(); id.emplace(s, x); names.push_back(s); }
            else x = it->second;
            trans[t].push_back(x);
        }
    }
    int U = (int)names.size(), W = (T + 63) / 64;
    // rank[x] orders products by name, so comparing ranks compares names.
    vector<int> byName(U), rank_(U);
    iota(byName.begin(), byName.end(), 0);
    sort(byName.begin(), byName.end(), [&](int a, int b) { return names[a] < names[b]; });
    for (int i = 0; i < U; i++) rank_[byName[i]] = i;
    // Each product gets a bitmask of the transactions it appears in.
    vector<unsigned long long> mask((size_t)U * W, 0);
    for (int t = 0; t < T; t++) {
        auto &v = trans[t];
        for (int &x : v) x = rank_[x];
        sort(v.begin(), v.end());
        v.erase(unique(v.begin(), v.end()), v.end());
        for (int r : v) mask[(size_t)byName[r] * W + t / 64] |= 1ULL << (t % 64);
    }
    int best = 0, ansA = -1, ansB = -1;
    for (int t = 0; t < T; t++) {
        auto &v = trans[t];
        for (size_t i = 0; i < v.size(); i++) {
            const unsigned long long *ma = &mask[(size_t)byName[v[i]] * W];
            for (size_t j = i + 1; j < v.size(); j++) {
                const unsigned long long *mb = &mask[(size_t)byName[v[j]] * W];
                int f = 0;
                for (int w = 0; w < W; w++) f += __builtin_popcountll(ma[w] & mb[w]);
                // Pair frequency is the size of the intersection; ties go to the smaller name pair.
                if (f > best || (f == best && (ansA < 0 || make_pair(v[i], v[j]) < make_pair(ansA, ansB)))) {
                    best = f; ansA = v[i]; ansB = v[j];
                }
            }
        }
    }
    if (ansA < 0) puts("-1");
    else printf("%s %s\n", names[byName[ansA]].c_str(), names[byName[ansB]].c_str());
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    static final InputStream in = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int gc() throws IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    static final StringBuilder sb = new StringBuilder();

    static String token() throws IOException {
        int c = gc();
        while (c != -1 && c <= ' ') c = gc();
        sb.setLength(0);
        while (c > ' ') { sb.append((char) c); c = gc(); }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int T = Integer.parseInt(token());
        HashMap<String, Integer> id = new HashMap<>();
        List<String> names = new ArrayList<>();
        int[][] trans = new int[T][];
        for (int t = 0; t < T; t++) {
            int k = Integer.parseInt(token());
            trans[t] = new int[k];
            for (int i = 0; i < k; i++) {
                String s = token();
                Integer x = id.get(s);
                if (x == null) { x = names.size(); id.put(s, x); names.add(s); }
                trans[t][i] = x;
            }
        }
        int U = names.size(), W = (T + 63) / 64;
        // rank[x] orders products by name, so comparing ranks compares names.
        Integer[] byNameBoxed = new Integer[U];
        for (int i = 0; i < U; i++) byNameBoxed[i] = i;
        Arrays.sort(byNameBoxed, (a, b) -> names.get(a).compareTo(names.get(b)));
        int[] byName = new int[U], rank = new int[U];
        for (int i = 0; i < U; i++) { byName[i] = byNameBoxed[i]; rank[byName[i]] = i; }
        // Each product (by rank) gets a bitmask of the transactions it appears in.
        long[] mask = new long[U * W];
        for (int t = 0; t < T; t++) {
            int[] v = trans[t];
            for (int i = 0; i < v.length; i++) v[i] = rank[v[i]];
            Arrays.sort(v);
            int u = 0;
            for (int i = 0; i < v.length; i++) if (i == 0 || v[i] != v[i - 1]) v[u++] = v[i];
            trans[t] = Arrays.copyOf(v, u);
            for (int i = 0; i < u; i++) mask[v[i] * W + t / 64] |= 1L << (t % 64);
        }
        int best = 0, ansA = -1, ansB = -1;
        for (int t = 0; t < T; t++) {
            int[] v = trans[t];
            for (int i = 0; i < v.length; i++) {
                int oa = v[i] * W;
                for (int j = i + 1; j < v.length; j++) {
                    int ob = v[j] * W, f = 0;
                    for (int w = 0; w < W; w++) f += Long.bitCount(mask[oa + w] & mask[ob + w]);
                    // Pair frequency is the size of the intersection; ties go to the smaller name pair.
                    if (f > best || (f == best && (ansA < 0 || v[i] < ansA || (v[i] == ansA && v[j] < ansB)))) {
                        best = f; ansA = v[i]; ansB = v[j];
                    }
                }
            }
        }
        if (ansA < 0) System.out.println(-1);
        else System.out.println(names.get(byName[ansA]) + " " + names.get(byName[ansB]));
    }
}

package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
	"slices"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<16), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() string { sc.Scan(); return sc.Text() }
	T, _ := strconv.Atoi(next())
	id := map[string]int{}
	var names []string
	trans := make([][]int, T)
	for t := 0; t < T; t++ {
		k, _ := strconv.Atoi(next())
		for i := 0; i < k; i++ {
			s := next()
			x, ok := id[s]
			if !ok {
				x = len(names)
				id[s] = x
				names = append(names, s)
			}
			trans[t] = append(trans[t], x)
		}
	}
	U, W := len(names), (T+63)/64
	// rank[x] orders products by name, so comparing ranks compares names.
	byName := make([]int, U)
	for i := range byName {
		byName[i] = i
	}
	sort.Slice(byName, func(a, b int) bool { return names[byName[a]] < names[byName[b]] })
	rank := make([]int, U)
	for i, x := range byName {
		rank[x] = i
	}
	// Each product (by rank) gets a bitmask of the transactions it appears in.
	mask := make([]uint64, U*W)
	for t := range trans {
		v := trans[t]
		for i := range v {
			v[i] = rank[v[i]]
		}
		slices.Sort(v)
		v = slices.Compact(v)
		trans[t] = v
		for _, r := range v {
			mask[r*W+t/64] |= 1 << (t % 64)
		}
	}
	best, ansA, ansB := 0, -1, -1
	for _, v := range trans {
		for i := range v {
			ma := mask[v[i]*W : v[i]*W+W]
			for j := i + 1; j < len(v); j++ {
				mb := mask[v[j]*W : v[j]*W+W]
				f := 0
				for w := range ma {
					f += bits.OnesCount64(ma[w] & mb[w])
				}
				// Pair frequency is the size of the intersection; ties go to the smaller name pair.
				if f > best || (f == best && (ansA < 0 || v[i] < ansA || (v[i] == ansA && v[j] < ansB))) {
					best, ansA, ansB = f, v[i], v[j]
				}
			}
		}
	}
	if ansA < 0 {
		fmt.Println(-1)
	} else {
		fmt.Println(names[byName[ansA]], names[byName[ansB]])
	}
}
